from pathlib import Path
import os,subprocess,json
src=Path('/srv/fadego-staging')
dest=Path('/srv/projects/fadego')
def cp(args,t=15):
 return subprocess.run(args,capture_output=True,text=True,timeout=t)
def active(name):
 return cp(['systemctl','is-active',name+'.service'],9).stdout.strip()
def bots():
 p=cp(['pm2','jlist'],14)
 if p.returncode:raise RuntimeError('PM2 unavailable')
 return {a.get('name'):{'status':(a.get('pm2_env') or {}).get('status'),'pid':a.get('pid')} for a in json.loads(p.stdout) if a.get('name') in ('telegram-robot-leads','iptvpn_bot')}
names=['fadego-staging','pink-iptv-backend','pink-vpn','lowcost-europa','pm2-root','nginx','postgresql@16-main']
units={n:active(n) for n in names}
if any(v!='active' for v in units.values()):raise RuntimeError('Pre-existing inactive service; no move')
before_bots=bots()
if any(before_bots.get(x,{}).get('status')!='online' for x in ('telegram-robot-leads','iptvpn_bot')):raise RuntimeError('Bot baseline offline')
if not src.is_dir() or src.is_symlink() or dest.exists() or dest.is_symlink():raise RuntimeError('Fadego root mismatch')
if not dest.parent.is_dir() or dest.parent.is_symlink() or src.stat().st_dev!=dest.parent.stat().st_dev:raise RuntimeError('Canonical parent/filesystem mismatch')
current=src/'current'
if not current.is_symlink():raise RuntimeError('Fadego active release pointer not verified')
original_link=os.readlink(current)
if not original_link.startswith(str(src/'releases')+'/'):raise RuntimeError('Expected old absolute active release missing')
release=Path(original_link).name
if not (src/'releases'/release).is_dir():raise RuntimeError('Active release missing')
original_inode=src.stat().st_ino
rel_inode=(src/'releases'/release).stat().st_ino
p=cp(['du','-x','-s','-B1',str(src)],55)
if p.returncode:raise RuntimeError('Could not measure Fadego')
size=int(p.stdout.split()[0])
serviceinfo=cp(['systemctl','show','fadego-staging.service','-p','MainPID','-p','WorkingDirectory','--no-pager'],9)
info=dict(x.split('=',1) for x in serviceinfo.stdout.splitlines() if '=' in x)
pid=info.get('MainPID','0')
if not pid.isdigit() or int(pid)<2 or info.get('WorkingDirectory')!=str(src/'current'):raise RuntimeError('Fadego service not in expected release')
print('BEFORE_RELEASE='+release)
print('BYTES='+str(size))
moved=False
changed_link=False
try:
 src.rename(dest);moved=True
 src.symlink_to(dest,target_is_directory=True)
 if not src.is_symlink() or src.resolve()!=dest or dest.stat().st_ino!=original_inode:raise RuntimeError('Canonical root missing')
 nowcurrent=dest/'current'
 temp=dest/'.fadego_current_repoint_tmp'
 if temp.exists() or temp.is_symlink():raise RuntimeError('Temporary link unexpectedly exists')
 temp.symlink_to('releases/'+release)
 os.replace(temp,nowcurrent)
 changed_link=True
 if nowcurrent.resolve()!=(dest/'releases'/release) or nowcurrent.stat().st_ino!=rel_inode:raise RuntimeError('Canonical release symlink resolution failed')
 if not (dest/'current/node_modules/next/dist/bin/next').is_file():raise RuntimeError('Active Next.js binary not found')
 q=cp(['du','-x','-s','-B1',str(dest)],55)
 if q.returncode or abs(int(q.stdout.split()[0])-size)>40960:raise RuntimeError('Unexpected size change')
 r=cp(['systemctl','show','fadego-staging.service','-p','MainPID','--no-pager'],9)
 if r.stdout.strip()!='MainPID='+pid:raise RuntimeError('Fadego process restarted')
 for name,s in units.items():
  if active(name)!=s:raise RuntimeError('Service state changed: '+name)
 if bots()!=before_bots:raise RuntimeError('Telegram bot PID or status changed')
except Exception:
 if changed_link:
  temp=dest/'.fadego_current_repoint_rollback'
  temp.symlink_to(original_link)
  os.replace(temp,dest/'current')
 if src.is_symlink() and src.resolve()==dest:src.unlink()
 if moved and dest.exists() and not src.exists():dest.rename(src)
 print('FADEGO_MOVE_ROLLBACK_APPLIED=YES')
 raise
print('FADEGO_PHYSICAL_DIR='+str(dest))
print('FADEGO_OLD_PATH='+str(src)+' (SYMLINK)')
print('FADEGO_CURRENT_LINK='+os.readlink(dest/'current'))
print('FADEGO_RELEASE_INODE_VERIFIED=YES')
print('FADEGO_PROCESS_PID_UNCHANGED='+pid)
print('OTHER_SYSTEMD_AND_BOTS=UNCHANGED')
print('FADEGO_NAME_ALIGNED_WITH_GITHUB=YES')
print('BYTES_REORGANIZED='+str(size))
print('DISK_BYTES_FREED=0')
print('FADEGO_ROOT_MOVE=PASS')
PY
